fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> Vec<Vec<String>> {
    a.into_iter()
        .map(|s| {
            if maxsplit == 0 {
                // If maxsplit is 0, return the original string as a single-element vector
                vec![s]
            } else if s.is_empty() {
                // If the string is empty, return a vector with an empty string
                vec!["".to_string()]
            } else {
                // Perform the right-split operation
                s.rsplitn((maxsplit + 1) as usize, &sep).map(String::from).collect()
            }
        })
        .collect()
}